bool RuntimeEnabledFeaturesBase::BlinkExtensionChromeOSEnabled(const FeatureContext* context) {
  if(context && context->GetRuntimeFeatureStateOverrideContext()
                    ->IsBlinkExtensionChromeOSForceEnabled()) {
    return true;
  }
  if(context && context->GetRuntimeFeatureStateOverrideContext()
                    ->IsBlinkExtensionChromeOSForceDisabled()) {
    return false;
  }

  return BlinkExtensionChromeOSEnabled();
}

